 // G��G�� State G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G�� var TOKEN = getToken(); var currentUser = null; var currentAction = null; var SETTINGS_KEY  = 'eams_control_settings'; var MAINT_KEY     = 'eams_maintenance';  // G��G�� Guard G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G�� 
(function() { currentUser = checkAuth('admin'); if (!currentUser) return; loadOverview(); loadHealth(); refreshExportCount(); })();
  // G��G�� Clock G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G�� function updateClock() {   var now = new Date();   document.getElementById('top-time').textContent = now.toLocaleTimeString('en-IN', { hour:'2-digit', minute:'2-digit', second:'2-digit' }); } updateClock(); setInterval(updateClock, 1000);  // G��G�� Nav G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G�� var PAGE_NAMES = ['overview','data','backup','undo','maintenance','settings','security','advanced'];  function nav(page) {   document.querySelectorAll('.pg').forEach(function(el) { el.classList.remove('act'); });   var pg = document.getElementById('pg-' + page);   if (pg) pg.classList.add('act');   document.querySelectorAll('.sb-item').forEach(function(el) { el.classList.remove('act'); });   var idx = PAGE_NAMES.indexOf(page);   var items = document.querySelectorAll('.sb-item');   if (idx >= 0 && items[idx]) items[idx].classList.add('act');   if (page === 'overview')    { loadOverview(); loadHealth(); }   if (page === 'data')        refreshExportCount();   if (page === 'backup')      loadBackupPage();   if (page === 'undo')        loadUndoPage();   if (page === 'maintenance') loadMaintenance(); }  // G��G�� API helper G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G�� function apiCall(method, path, body) {   var tok = sessionStorage.getItem('eams_token') || TOKEN || '';   return fetch('/api' + path, {     method: method,     headers: { 'Content-Type':'application/json', 'Authorization':'Bearer '+tok },     body: body ? JSON.stringify(body) : undefined   }).then(function(r) { return r.json(); }); }  // G��G�� Overview G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G�� function loadOverview() {   // Show maintenance banner from DB   apiCall('GET', '/settings/maintenance').then(function(maint) {     var banner = document.getElementById('maint-banner');     if (banner) {       if (maint && maint.active) banner.classList.remove('hidden');       else banner.classList.add('hidden');     }   }).catch(function(){});    var tok = sessionStorage.getItem('eams_token') || TOKEN || '';   var h   = { 'Authorization': 'Bearer ' + tok };    // Fetch real DB stats from server   if (!tok) {     document.getElementById('ov-storage-desc').textContent = 'Not logged in via API G�� please log out and log back in.';     logLine('No auth token G�� log out and log in again to use API features', 'warn');     return;   }   fetch('/api/system/dbstats', { headers: h })     .then(function(r) {       if (r.status === 401) throw new Error('Unauthorized G�� token invalid or expired');       return r.json();     })     .then(function(d) {       if (d.error) { logLine('DB stats error: ' + d.error, 'danger'); document.getElementById('ov-storage-desc').textContent = 'Error: ' + d.error; return; }        // Top cards       document.getElementById('ov-data-size').textContent    = d.dataSize    + ' MB';       document.getElementById('ov-storage-size').textContent = d.storageSize + ' MB';       document.getElementById('ov-index-size').textContent   = d.indexSize   + ' MB';       document.getElementById('ov-total-docs').textContent   = d.totalDocs;        // Storage bar       var used  = parseFloat(d.storageSize);       var total = d.fsTotalSize ? parseFloat(d.fsTotalSize) : null;       var free  = total ? (total - parseFloat(d.fsUsedSize || used)) : null;       var pct   = total ? Math.min(100, (parseFloat(d.fsUsedSize || used) / total * 100)).toFixed(1) : null;        var bar  = document.getElementById('ov-storage-bar');       var desc = document.getElementById('ov-storage-desc');       var usedLbl  = document.getElementById('ov-used-label');       var freeLbl  = document.getElementById('ov-free-label');       var totalLbl = document.getElementById('ov-total-label');        if (total) {         bar.style.width = pct + '%';         bar.style.background = pct > 80 ? 'linear-gradient(90deg,#dc2626,#ef4444)'                               : pct > 60 ? 'linear-gradient(90deg,#d97706,#fbbf24)'                               : 'linear-gradient(90deg,#2e7d32,#66bb6a)';         desc.textContent = 'Disk: ' + pct + '% used of ' + total + ' MB total';         usedLbl.textContent  = 'Used: '  + parseFloat(d.fsUsedSize).toFixed(0)  + ' MB';         freeLbl.textContent  = 'Free: '  + free.toFixed(0)  + ' MB';         totalLbl.textContent = 'Total: ' + total + ' MB';       } else {         // Atlas free tier G�� show data size vs 512MB limit         var limit = 512;         var usedMB = parseFloat(d.storageSize);         var pctUsed = Math.min(100, (usedMB / limit * 100)).toFixed(1);         bar.style.width = pctUsed + '%';         bar.style.background = pctUsed > 80 ? 'linear-gradient(90deg,#dc2626,#ef4444)'                               : pctUsed > 60 ? 'linear-gradient(90deg,#d97706,#fbbf24)'                               : 'linear-gradient(90deg,#2e7d32,#66bb6a)';         desc.textContent     = 'Atlas Free Tier G�� ' + pctUsed + '% of 512 MB used';         usedLbl.textContent  = 'Used: '  + usedMB.toFixed(2) + ' MB';         freeLbl.textContent  = 'Free: '  + (limit - usedMB).toFixed(2) + ' MB';         totalLbl.textContent = 'Total: ' + limit + ' MB (Atlas Free Tier)';       }        // Collection breakdown grid       var grid = document.getElementById('collection-grid');       if (grid && d.collStats) {         grid.innerHTML = d.collStats.map(function(c) {           return '<div style="background:#f8fafc;border-radius:10px;padding:12px 14px;display:flex;align-items:center;gap:10px;">'             + '<div><div style="font-size:11px;color:var(--tmu);font-weight:600;text-transform:capitalize;">' + c.name + '</div>'             + '<div style="font-size:20px;font-weight:800;color:var(--td);">' + c.count + '</div></div></div>';         }).join('');       }        logLine('DB stats loaded G�� ' + d.totalDocs + ' docs, ' + d.dataSize + ' MB data', 'success');     })     .catch(function(err) {       logLine('Failed to load DB stats: ' + (err.message || 'network error'), 'danger');       document.getElementById('ov-storage-desc').textContent = 'Could not fetch storage info G�� check server connection';     }); } // G��G�� Log terminal G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G�� function logLine(msg, type) {   type = type || 'info';   var el = document.getElementById('sys-log');   if (!el) return;   var line = document.createElement('div');   line.className = 'terminal-line ' + type;   var ts = new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',second:'2-digit'});   line.innerHTML = '<span class="terminal-prompt">['+ts+']</span> ' + msg;   el.appendChild(line);   el.scrollTop = el.scrollHeight; }  // G��G�� Settings (localStorage) G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G�� function getSettings(key) {   try { return JSON.parse(localStorage.getItem(key) || 'null'); } catch(e){ return null; } } function setSettings(key, val) {   localStorage.setItem(key, JSON.stringify(val)); }  // G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G�� //  MAINTENANCE G�� fully DB-backed // G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G�� var _maintData = null;  function loadMaintenance() {   // Reset UI to loading state   document.getElementById('ms-active-val').textContent  = 'FetchingGǪ';   document.getElementById('ms-active-val').style.color  = 'var(--tdi)';   document.getElementById('ms-roles-val').textContent   = 'GǪ';   document.getElementById('ms-end-val').textContent     = 'GǪ';   document.getElementById('ms-started-val').textContent = 'GǪ';   document.getElementById('ms-msg-val').textContent     = 'GǪ';   var tb = document.getElementById('maint-toggle-main-btn');   tb.disabled = true; tb.textContent = 'LoadingGǪ';   document.getElementById('maint-log-list').innerHTML =     '<div style="text-align:center;padding:20px;color:var(--tdi);font-size:13px;">GŦ Loading logs from databaseGǪ</div>';    apiCall('GET', '/settings/maintenance').then(function(d) {     if (!d || d.error) { showToast('G��n+� ' + (d && d.error ? d.error : 'Load failed')); return; }     _maintData = d;     renderMaintUI(d);     // Start expiry polling if already active with an end time     if (d.active && d.endTime) {       if (Date.now() >= new Date(d.endTime).getTime()) {         showExpiryDialog(); // already expired G�� show immediately       } else {         startExpiryPolling();       }     }   }).catch(function(e) {     showToast('G�� Failed to load: ' + e.message);     document.getElementById('ms-active-val').textContent = 'Error';     document.getElementById('ms-active-val').style.color = '#dc2626';     tb.textContent = 'Retry';     tb.disabled = false;   });    loadMaintLogs();   loadServerLogs(); }  function renderMaintUI(d) {   if (!d) return;   var isActive = !!d.active;   var affected = d.affectedRoles || [];    // G��G�� Status Banner   var banner     = document.getElementById('maint-status-banner');   var bannerIcon = document.getElementById('maint-banner-icon');   var bannerTitle= document.getElementById('maint-banner-title');   var bannerSub  = document.getElementById('maint-banner-sub');   var toggleBtn  = document.getElementById('maint-toggle-main-btn');   toggleBtn.disabled = false;    if (isActive) {     banner.style.background  = 'linear-gradient(135deg,#fff3cd,#fff8e1)';     banner.style.borderColor = '#f59e0b';     bannerIcon.textContent   = '=���';     bannerTitle.textContent  = 'Maintenance Mode is ACTIVE';     var rLabels = affectedRoleLabels(affected);     bannerSub.textContent = (rLabels.length ? rLabels.join(', ') + ' are blocked.' : 'No roles blocked.') + ' Admins retain full access.';     toggleBtn.textContent      = 'G�� Disable Maintenance';     toggleBtn.style.background = '#dc2626';     toggleBtn.style.color      = '#fff';     var tb = document.getElementById('maint-banner');     if (tb) tb.classList.remove('hidden');   } else {     banner.style.background  = 'linear-gradient(135deg,#f0fdf4,#ecfdf5)';     banner.style.borderColor = '#4ade80';     bannerIcon.textContent   = '=���';     bannerTitle.textContent  = 'System is Online G�� All users can log in';     bannerSub.textContent    = 'Configure roles, end time and message below, then enable.';     toggleBtn.textContent      = 'G��n+� Enable Maintenance';     toggleBtn.style.background = '#f59e0b';     toggleBtn.style.color      = '#fff';     var tb2 = document.getElementById('maint-banner');     if (tb2) tb2.classList.add('hidden');   }    // G��G�� Form fields   ['teacher','student','subadmin'].forEach(function(r) {     var cb = document.getElementById('maint-role-' + r);     if (cb) cb.checked = affected.includes(r);     updateRoleChip(r);   });    // End time G�� convert UTC G�� local datetime-local value   if (d.endTime) {     var dt = new Date(d.endTime);     document.getElementById('maint-end-time').value =       new Date(dt.getTime() - dt.getTimezoneOffset() * 60000).toISOString().slice(0,16);     document.getElementById('maint-end-time').style.borderColor = '#e2e8f0';   } else {     document.getElementById('maint-end-time').value = '';   }   document.getElementById('maint-msg').value = d.message || '';    // G��G�� State card   var activeEl = document.getElementById('ms-active-val');   activeEl.textContent = isActive ? '=��� ENABLED' : '=��� Disabled';   activeEl.style.color = isActive ? '#dc2626' : '#16a34a';    var rLabels2 = affectedRoleLabels(affected);   document.getElementById('ms-roles-val').textContent    = rLabels2.length ? rLabels2.join(', ') : 'None selected';   document.getElementById('ms-end-val').textContent      = d.endTime ? fmtDateTime(d.endTime) : 'G��n+� Not set';   document.getElementById('ms-started-val').textContent  = d.startedAt ? fmtDateTime(d.startedAt) : (isActive ? 'Now' : 'G��');   document.getElementById('ms-msg-val').textContent      = d.message || 'G��';    // G��G�� Role access table   renderRoleTable(isActive, affected); }  function affectedRoleLabels(affected) {   var map = { teacher: 'Teachers', student: 'Students', subadmin: 'Sub-Admins' };   return (affected || []).map(function(r) { return map[r] || r; }); }  function fmtDateTime(str) {   try { return new Date(str).toLocaleString('en-IN', { dateStyle:'medium', timeStyle:'short', hour12:true }); }   catch(e) { return str; } }  function updateRoleChip(role) {   var cb   = document.getElementById('maint-role-' + role);   var lbl  = document.getElementById('role-lbl-' + role);   var chip = document.getElementById('role-chip-' + role);   if (!cb || !lbl || !chip) return;   if (cb.checked) {     lbl.style.background  = '#fff7ed';     lbl.style.borderColor = '#f59e0b';     chip.textContent      = 'Will be blocked';     chip.style.background = '#fef3c7';     chip.style.color      = '#92400e';   } else {     lbl.style.background  = '#f8fafc';     lbl.style.borderColor = '#e2e8f0';     chip.textContent      = 'Not blocked';     chip.style.background = '#f3f4f6';     chip.style.color      = '#6b7280';   } }  function getSelectedRoles() {   return ['teacher','student','subadmin'].filter(function(r) {     var cb = document.getElementById('maint-role-' + r);     return cb && cb.checked;   }); }  function saveMaintConfig() {   var roles  = getSelectedRoles();   var msg    = (document.getElementById('maint-msg').value || '').trim();   var endVal = document.getElementById('maint-end-time').value;   var endEl  = document.getElementById('maint-end-time');    // Validate required fields   if (!msg) { showToast('G��n+� Message is required.'); return; }   if (!endVal) {     endEl.style.borderColor = '#dc2626';     showToast('G��n+� End date & time is required G�� shown as countdown to users.');     endEl.focus();     return;   }   endEl.style.borderColor = '#e2e8f0';    var endISO = new Date(endVal).toISOString();    var payload = {     value: {       active:        _maintData ? !!_maintData.active : false,       message:       msg,       affectedRoles: roles,       endTime:       endISO,       startedAt:     (_maintData && _maintData.startedAt) ? _maintData.startedAt : null,     }   };    apiCall('PUT', '/settings/maintenance', payload).then(function(d) {     if (d && d.error) { showToast('G�� ' + d.error); return; }     _maintData = d;     renderMaintUI(d);     showToast('G�� Configuration saved to database');     logLine('Maintenance config saved G�� roles: [' + roles.join(', ') + '] end: ' + fmtDateTime(endISO), 'success');     loadMaintLogs();   }).catch(function(e) { showToast('G�� Save failed: ' + e.message); }); }  function doToggleMaintenance() {   if (!_maintData) { showToast('G��n+� Settings not loaded yet.'); return; }   var roles  = getSelectedRoles();   var msg    = (document.getElementById('maint-msg').value || '').trim() || 'System is under maintenance. Please try again later.';   var endVal = document.getElementById('maint-end-time').value;   var endEl  = document.getElementById('maint-end-time');   var nowActive = !_maintData.active;    // Validate before enabling   if (nowActive) {     if (roles.length === 0) { showToast('G��n+� Select at least one role to block.'); return; }     if (!endVal) {       endEl.style.borderColor = '#dc2626';       showToast('G��n+� End date & time is required to show countdown on maintenance page.');       endEl.focus();       return;     }   }   endEl.style.borderColor = '#e2e8f0';    var endISO = endVal ? new Date(endVal).toISOString() : null;   var payload = {     value: {       active:        nowActive,       message:       msg,       affectedRoles: roles,       endTime:       endISO,       startedAt:     nowActive ? new Date().toISOString() : null,     }   };    var toggleBtn = document.getElementById('maint-toggle-main-btn');   toggleBtn.disabled  = true;   toggleBtn.textContent = nowActive ? 'EnablingGǪ' : 'DisablingGǪ';    apiCall('PUT', '/settings/maintenance', payload).then(function(d) {     if (d && d.error) { showToast('G�� ' + d.error); toggleBtn.disabled = false; return; }     _maintData = d;     renderMaintUI(d);     var msg2 = nowActive       ? '=��� Maintenance ENABLED G�� ' + affectedRoleLabels(roles).join(', ') + ' redirected to maintenance page'       : 'G�� Maintenance DISABLED G�� All users can now log in';     showToast(msg2);     logLine(nowActive ? 'MAINTENANCE ENABLED' : 'MAINTENANCE DISABLED', nowActive ? 'warn' : 'success');     loadMaintLogs();     loadServerLogs();     // Start expiry polling when enabled; stop when disabled     if (nowActive && d.endTime) {       startExpiryPolling();     } else if (!nowActive && _expiryPollInterval) {       clearInterval(_expiryPollInterval);       _expiryPollInterval = null;       document.getElementById('maint-expiry-modal').classList.remove('open');     }   }).catch(function(e) {     showToast('G�� Toggle failed: ' + e.message);     toggleBtn.disabled = false;   }); }  function setMaintPreset(hours) {   var end = new Date(Date.now() + hours * 3600000);   document.getElementById('maint-end-time').value =     new Date(end.getTime() - end.getTimezoneOffset() * 60000).toISOString().slice(0,16);   document.getElementById('maint-end-time').style.borderColor = '#e2e8f0';   showToast('GŦ End time set: +' + hours + ' hr' + (hours > 1 ? 's' : '')); }  function selectAllRoles() {   ['teacher','student','subadmin'].forEach(function(r) {     var cb = document.getElementById('maint-role-' + r);     if (cb) cb.checked = true;     updateRoleChip(r);   }); }  function clearAllRoles() {   ['teacher','student','subadmin'].forEach(function(r) {     var cb = document.getElementById('maint-role-' + r);     if (cb) cb.checked = false;     updateRoleChip(r);   }); }  function teachersOnly() {   clearAllRoles();   var cb = document.getElementById('maint-role-teacher');   if (cb) cb.checked = true;   updateRoleChip('teacher'); }  function studentsOnly() {   clearAllRoles();   var cb = document.getElementById('maint-role-student');   if (cb) cb.checked = true;   updateRoleChip('student'); }  function renderRoleTable(maintActive, affected) {   affected = affected || [];   // When maintenance is OFF nobody is blocked regardless of checkbox state   var roles = [     { role:'Admin',     icon:'=���',       blocked: false,       note: 'Always has full access' },     { role:'Teacher',   icon:'=��G��=�Ž',       blocked: maintActive && affected.includes('teacher'),       note: (maintActive && affected.includes('teacher')) ? 'Blocked G�� shown maintenance page' : 'Full access' },     { role:'Student',   icon:'=��G��=���',       blocked: maintActive && affected.includes('student'),       note: (maintActive && affected.includes('student')) ? 'Blocked G�� shown maintenance page' : 'Full access' },     { role:'Sub-Admin', icon:'=���G��=��+',       blocked: maintActive && affected.includes('subadmin'),       note: (maintActive && affected.includes('subadmin')) ? 'Blocked G�� shown maintenance page' : 'Full access' },   ];   document.getElementById('role-access-table').innerHTML = roles.map(function(r) {     var color  = r.blocked ? '#dc2626' : '#16a34a';     var bg     = r.blocked ? '#fef2f2' : '#f0fdf4';     var status = r.blocked ? '=��� Blocked' : 'G�� OK';     return '<div style="display:flex;align-items:center;justify-content:space-between;padding:9px 12px;background:' + bg + ';border-radius:10px;">'       + '<div style="display:flex;align-items:center;gap:9px;">'       + '<span style="font-size:17px;">' + r.icon + '</span>'       + '<div><div style="font-weight:600;font-size:12.5px;color:' + color + ';">' + r.role + '</div>'       + '<div style="font-size:10.5px;color:var(--tmu);">' + r.note + '</div></div></div>'       + '<span style="font-size:11.5px;font-weight:700;color:' + color + ';">' + status + '</span>'       + '</div>';   }).join(''); }  // G��G�� Maintenance Activity Log (from DB) G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G�� function loadMaintLogs() {   var el = document.getElementById('maint-log-list');   el.innerHTML = '<div style="text-align:center;padding:16px;color:var(--tdi);font-size:12px;">GŦ Loading from databaseGǪ</div>';    apiCall('GET', '/logs/maintenance').then(function(logs) {     if (!logs || !logs.length) {       el.innerHTML = '<div style="text-align:center;padding:24px;color:var(--tdi);font-size:13px;">=��� No maintenance events logged yet. Enable/disable maintenance to create logs.</div>';       return;     }     el.innerHTML = logs.map(function(l) {       var isEnable  = l.action && l.action.toLowerCase().includes('enabl');       var isDisable = l.action && l.action.toLowerCase().includes('disabl');       var dotColor  = isEnable ? '#f59e0b' : isDisable ? '#22c55e' : '#3b82f6';       var sev       = l.severity || 'info';       var sevColor  = sev === 'warning' ? '#f59e0b' : sev === 'critical' ? '#dc2626' : '#16a34a';       return '<div style="display:flex;align-items:flex-start;gap:10px;padding:9px 0;border-bottom:1px solid var(--brl);">'         + '<div style="width:8px;height:8px;border-radius:50%;background:' + dotColor + ';flex-shrink:0;margin-top:5px;"></div>'         + '<div style="flex:1;min-width:0;">'         + '<div style="font-size:12.5px;font-weight:700;color:var(--td);">' + (l.action || 'G��') + '</div>'         + '<div style="font-size:11px;color:var(--tmu);margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">'         + (l.userName || '') + (l.details ? ' -+ ' + l.details : '') + '</div></div>'         + '<div style="font-size:10px;color:var(--tdi);white-space:nowrap;padding-top:2px;">' + fmtDateTime(l.time) + '</div>'         + '</div>';     }).join('');   }).catch(function(e) {     el.innerHTML = '<div style="padding:16px;color:#dc2626;font-size:12px;">G�� Failed to load logs: ' + e.message + '</div>';   }); }  // G��G�� Server Logs (live Node.js output) G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G�� var _srvLogPollInterval = null; var _srvLogSince = null;  function loadServerLogs() {   var url = '/api/system/serverlogs' + (_srvLogSince ? '?since=' + encodeURIComponent(_srvLogSince) : '');   apiCall('GET', url).then(function(d) {     if (!d) return;      // Update meta     document.getElementById('srv-uptime').textContent = formatUptime(d.uptime);     document.getElementById('srv-mem').textContent    = d.memMB + ' MB';     document.getElementById('srv-node').textContent   = d.nodeVersion || 'G��';     document.getElementById('srv-env').textContent    = d.env || 'G��';      if (d.logs && d.logs.length) {       var terminal = document.getElementById('srv-log-terminal');       var wasBottom = terminal.scrollHeight - terminal.scrollTop <= terminal.clientHeight + 20;        // Append new lines       var frag = d.logs.map(function(l) {         var cls = l.level === 'error' ? 'danger' : l.level === 'warn' ? 'warn' : 'success';         // Colour specific patterns         if (l.text.includes('G��') || l.text.includes('connected') || l.text.includes('seeded')) cls = 'success';         if (l.text.includes('G��') || l.text.includes('error') || l.text.includes('Error'))      cls = 'danger';         if (l.text.includes('G��n+�') || l.text.includes('warn') || l.text.includes('MAINT'))       cls = 'warn';         if (l.text.includes('=���') || l.text.includes('=��') || l.text.includes('G�n+�'))            cls = 'info';         var ts = new Date(l.time).toLocaleTimeString('en-IN', {hour:'2-digit',minute:'2-digit',second:'2-digit'});         return '<div class="terminal-line ' + cls + '"><span class="terminal-prompt">[' + ts + ']</span>' + escHtml(l.text) + '</div>';       }).join('');        // On first load, replace; on poll, append       if (!_srvLogSince) {         terminal.innerHTML = frag || '<div class="terminal-line info">No logs yet.</div>';       } else {         terminal.insertAdjacentHTML('beforeend', frag);         // Keep max 300 lines in DOM         var lines = terminal.querySelectorAll('.terminal-line');         if (lines.length > 300) for (var i = 0; i < lines.length - 300; i++) lines[i].remove();       }        // Track since timestamp       _srvLogSince = d.logs[d.logs.length - 1].time;        // Auto-scroll if was at bottom       if (wasBottom) terminal.scrollTop = terminal.scrollHeight;     }   }).catch(function(e) {     if (!_srvLogSince) {       document.getElementById('srv-log-terminal').innerHTML =         '<div class="terminal-line danger">Failed to load server logs: ' + e.message + '</div>';     }   }); }  function escHtml(str) {   return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }  function formatUptime(secs) {   if (!secs) return 'G��';   var h = Math.floor(secs / 3600), m = Math.floor((secs % 3600) / 60), s = secs % 60;   if (h > 0) return h + 'h ' + m + 'm';   if (m > 0) return m + 'm ' + s + 's';   return s + 's'; }  function toggleServerLogPoll() {   var btn = document.getElementById('srvlog-poll-btn');   if (_srvLogPollInterval) {     clearInterval(_srvLogPollInterval);     _srvLogPollInterval = null;     btn.textContent = 'G�� Auto';     btn.style.background = '';     showToast('Auto-refresh stopped');   } else {     _srvLogPollInterval = setInterval(loadServerLogs, 3000);     btn.textContent = 'G�+ Stop';     btn.style.background = '#fef3c7';     showToast('Auto-refresh every 3s');     loadServerLogs();   } }  // G��G�� Maintenance Expiry Polling G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G�� var _expiryPollInterval = null; var _expiryDialogDismissed = false;      function dismissExpiryDialog() {   _expiryDialogDismissed = true;   document.getElementById('maint-expiry-modal').classList.remove('open');   showToast('G�n+� Dismissed G�� maintenance still active'); }  function extendMaintenance(hours) {   if (!_maintData) return;   var newEnd = new Date(Date.now() + hours * 3600000).toISOString();   var payload = {     value: {       active:        true,       message:       _maintData.message || '',       affectedRoles: _maintData.affectedRoles || [],       endTime:       newEnd,       startedAt:     _maintData.startedAt || new Date().toISOString(),     }   };   apiCall('PUT', '/settings/maintenance', payload).then(function(d) {     if (d && d.error) { showToast('G�� ' + d.error); return; }     _maintData = d;     renderMaintUI(d);     document.getElementById('maint-expiry-modal').classList.remove('open');     showToast('GŦ Extended +' + hours + ' hr' + (hours > 1 ? 's' : '') + ' G�� ends ' + fmtDateTime(newEnd));     logLine('Maintenance EXTENDED +' + hours + 'h G�� new end: ' + fmtDateTime(newEnd), 'warn');     loadMaintLogs();     startExpiryPolling(); // restart for the new end time   }).catch(function(e) { showToast('G�� Extend failed: ' + e.message); }); }  function disableMaintenanceFromExpiry() {   if (!_maintData) return;   var payload = {     value: {       active:        false,       message:       _maintData.message || '',       affectedRoles: _maintData.affectedRoles || [],       endTime:       null,       startedAt:     null,     }   };   apiCall('PUT', '/settings/maintenance', payload).then(function(d) {     if (d && d.error) { showToast('G�� ' + d.error); return; }     _maintData = d;     renderMaintUI(d);     document.getElementById('maint-expiry-modal').classList.remove('open');     showToast('G�� Maintenance DISABLED G�� System is back online');     logLine('Maintenance DISABLED after expiry', 'success');     loadMaintLogs();   }).catch(function(e) { showToast('G�� ' + e.message); }); }  // Legacy stubs function toggleMaintenance() { doToggleMaintenance(); } function saveMaintMsg() { saveMaintConfig(); } function updateMaintLabel() {}  function clearMaintEndTime() {   document.getElementById('maint-end-time').value = '';   document.getElementById('maint-end-time').style.borderColor = '#e2e8f0'; }   // G��G�� Toggle label sync G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G�� function syncLabel(checkbox, labelId) {   var lbl = document.getElementById(labelId);   lbl.textContent = checkbox.checked ? 'ON' : 'OFF';   lbl.className   = 'toggle-state ' + (checkbox.checked ? 'on' : 'off'); } // Wire security toggles ['sec-forcepw','sec-strongpw','sec-timeout'].forEach(function(id) {   var el = document.getElementById(id);   if (el) el.addEventListener('change', function() { syncLabel(this, id+'-label'); }); });  // G��G�� Save settings G�� writes to MongoDB first, then caches G��G�� function saveSettings(section) {   var payload = {};   if (section === 'institution') {     payload = {       name:  document.getElementById('inst-name').value,       short: document.getElementById('inst-short').value,       addr:  document.getElementById('inst-addr').value,       email: document.getElementById('inst-email').value,       phone: document.getElementById('inst-phone').value,     };   } else if (section === 'academic') {     payload = {       year:   document.getElementById('acad-year').value,       sem:    document.getElementById('acad-sem').value,       start:  document.getElementById('acad-start').value,       end:    document.getElementById('acad-end').value,       minAtt: document.getElementById('acad-minatt').value,       wdays:  document.getElementById('acad-wdays').value,     };   } else if (section === 'security') {     payload = {       forcePw:    document.getElementById('sec-forcepw').checked,       strongPw:   document.getElementById('sec-strongpw').checked,       timeout:    document.getElementById('sec-timeout').checked,       timeoutMin: document.getElementById('sec-timeout-mins').value,       maxLogin:   document.getElementById('sec-maxlogin').value,     };   }   showToast('GŦ Saving to MongoDBGǪ');   apiCall('PUT', '/settings/' + section, payload).then(function(d) {     if (d && d.error) { showToast('G�� Save failed: ' + d.error); return; }     // Cache locally as fallback     var cached = getSettings(SETTINGS_KEY) || {};     cached[section] = payload;     setSettings(SETTINGS_KEY, cached);     logLine('Settings saved to DB: ' + section, 'success');     showToast('G�� ' + section.charAt(0).toUpperCase()+section.slice(1) + ' settings saved to MongoDB');   }).catch(function(e) {     showToast('G�� Network error G�� settings NOT saved: ' + (e.message||''));     logLine('Settings save failed: ' + section + ' G�� ' + (e.message||'network error'), 'danger');   }); }  // G��G�� Load settings G�� DB-backed with localStorage fallback G��G�� function applySettingsToForm(s) {   var inst = s.institution || {};   var acad = s.academic    || {};   var sec  = s.security    || {};   function val(id, v) { var el=document.getElementById(id); if(el && v !== undefined && v !== null && v !== '') el.value = v; }   function chk(id, v) { var el=document.getElementById(id); if(el && v !== undefined) { el.checked = !!v; syncLabel(el, id+'-label'); } }   val('inst-name',  inst.name);   val('inst-short', inst.short);   val('inst-addr',  inst.addr);   val('inst-email', inst.email);   val('inst-phone', inst.phone);   val('acad-year',  acad.year);   val('acad-sem',   acad.sem);   val('acad-start', acad.start);  val('acad-end',   acad.end);   val('acad-minatt',acad.minAtt); val('acad-wdays', acad.wdays);   chk('sec-forcepw',  sec.forcePw);   chk('sec-strongpw', sec.strongPw);   chk('sec-timeout',  sec.timeout);   val('sec-timeout-mins', sec.timeoutMin);   val('sec-maxlogin',     sec.maxLogin); }  function showLoadingOverlay(show) {   var el = document.getElementById('page-loading-overlay');   if (!el) return;   if (show) { el.classList.remove('hidden'); }   else      { el.classList.add('hidden'); } }  function loadAllSettings() {   showLoadingOverlay(true);   // Set placeholder text while loading   ['inst-name','inst-short','inst-addr','inst-email','inst-phone','acad-year'].forEach(function(id) {     var el = document.getElementById(id);     if (el) el.placeholder = 'Loading from DBGǪ';   });   apiCall('GET', '/settings').then(function(d) {     if (d && !d.error) {       applySettingsToForm(d);       setSettings(SETTINGS_KEY, d); // cache locally as fallback       logLine('Settings loaded from MongoDB', 'success');     } else {       // Fallback to localStorage cache       var cached = getSettings(SETTINGS_KEY);       if (cached) { applySettingsToForm(cached); logLine('Settings loaded from local cache (DB unavailable)', 'warn'); }     }   }).catch(function() {     var cached = getSettings(SETTINGS_KEY);     if (cached) { applySettingsToForm(cached); logLine('Settings loaded from local cache (network error)', 'warn'); }   }).finally(function() {     showLoadingOverlay(false);   }); } loadAllSettings();  // G��G�� Admin password reset G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G�� function resetAdminPassword() {   var nw   = document.getElementById('admin-pw-new').value.trim();   var conf = document.getElementById('admin-pw-conf').value.trim();   if (!nw || !conf)     { showToast('G��n+� Please fill both fields', 'warn'); return; }   if (nw.length < 6)    { showToast('G��n+� Password must be at least 6 characters', 'warn'); return; }   if (nw !== conf)      { showToast('G��n+� Passwords do not match', 'warn'); return; }   apiCall('POST', '/auth/change-password', { currentPassword: prompt('Enter your current admin password:'), newPassword: nw })     .then(function(d) {       if (d.error) { showToast('G�� ' + d.error, 'danger'); return; }       document.getElementById('admin-pw-new').value  = '';       document.getElementById('admin-pw-conf').value = '';       logLine('Admin password reset successfully', 'success');       showToast('G�� Admin password updated successfully');     }).catch(function() { showToast('G�� Server error', 'danger'); }); }  // G��G�� Confirm modal G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G��G�� var ACTIONS = {   teachers:      { icon:'=���n+�', title:'Delete All Teachers?', body:'This will permanently delete ALL teacher accounts and their subject assignments. Admin account is NOT affected.', btn:'Delete Teachers', cls:'btn-danger' },   students:      { icon:'=���n+�', title:'Delete All Students?', body:'This will permanently delete ALL student records, their login accounts, and attendance data.', btn:'Delete Students', cls:'btn-danger' },   attendance:    { icon:'=���', title:'Clear Attendance?',    body:'This will permanently delete ALL attendance records. Students and teachers are kept.', btn:'Clear Attendance', cls:'btn-warn' },   logs:          { icon:'=���', title:'Clear Activity Logs?', body:'This will permanently delete ALL system logs and login history.', btn:'Clear Logs', cls:'btn-warn' },   clearall:      { icon:'=���', title:'Clear Entire Database?', body:'This will wipe ALL data: students, teachers, departments, classes, subjects, attendance, notifications, and logs. Your admin account will be preserved. This is IRREVERSIBLE.', btn:'Wipe Database', cls:'btn-danger' },   resetSettings: { icon:'G�',  title:'Reset All Settings?',  body:'All settings will be restored to factory defaults. Data is NOT affected.', btn:'Reset Settings', cls:'btn-warn' }, };  function openConfirm(action) {   currentAction = action;   var cfg = ACTIONS[action] || {};   document.getElementById('m-icon').textContent  = cfg.icon  || 'G��n+�';   document.getElementById('m-title').textContent = cfg.title || 'Are you sure?';   document.getElementById('m-body').textContent  = cfg.body  || 'This cannot be undone